// Replays testdata/reserve_sizing_vectors.json, generated by proto/go/zs
// TestReserveSizingVectors, against the SDK's reserve-phase pieces. Each body
// runs as a string and as bytes, the two forms a caller may hand the SDK.

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

import {
    BUSY_RETRIES,
    BUSY_RETRY_BUDGET_MS,
    BUSY_RETRY_DELAY_MS,
    BUSY_RETRY_MAX_DELAY_MS,
    DEFAULT_TOOL_HEADROOM_PER_ITERATION,
    MaxOutputRequiredError,
    RESERVE_MIN_INPUT_COUNT,
    TRANSIENT_RETRY_AFTER_HINT_MS,
    admitEstimate,
    advertisedMaxPrice,
    busyRetryWait,
    effectiveMaxOutput,
    estimate,
    extractMaxOutput,
    fits,
    maxDeclaredOutput,
    noFitMessage,
    parseImageRequestN,
    reserveInputCount,
    reserveSizeFailureMessage,
    resolveUsePrivacy,
    streamableRequest,
} from '../src/index.js'
import type { Operator, SizingRequest } from '../src/index.js'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any

const v: Json = JSON.parse(readFileSync(new URL('../../testdata/reserve_sizing_vectors.json', import.meta.url), 'utf8'))

type SizingOp = Pick<Operator, 'modelCapacities' | 'protoVersion' | 'maxToolIters' | 'toolHeadroomPerIteration'>

// Go writes a nil map as null; the SDK's operator always carries an object.
function opOf(o: Json): SizingOp {
    return { ...o, modelCapacities: o.modelCapacities ?? {} } as SizingOp
}

const forms = (body: string): (string | Uint8Array)[] => [body, new TextEncoder().encode(body)]

describe('reserve_sizing_vectors.json', () => {
    it('agrees on the constants', () => {
        expect({
            default_tool_headroom_per_iteration: DEFAULT_TOOL_HEADROOM_PER_ITERATION,
            reserve_min_input_count: RESERVE_MIN_INPUT_COUNT,
            busy_retries: BUSY_RETRIES,
            busy_retry_budget_ms: BUSY_RETRY_BUDGET_MS,
            busy_retry_delay_ms: BUSY_RETRY_DELAY_MS,
            busy_retry_max_delay_ms: BUSY_RETRY_MAX_DELAY_MS,
            transient_retry_after_hint_ms: TRANSIENT_RETRY_AFTER_HINT_MS,
        }).toEqual(v.constants)
    })

    describe('fits', () => {
        for (const c of v.fits) {
            it(c.name, () => {
                const op = opOf(c.op)
                expect(effectiveMaxOutput(op, c.sizing as SizingRequest)).toBe(c.effective_max_output)
                expect(fits(op, c.sizing as SizingRequest)).toBe(c.fits)
            })
        }
    })

    describe('maxDeclaredOutput', () => {
        for (const c of v.max_declared) {
            it(c.name, () => {
                expect(maxDeclaredOutput(c.ops.map(opOf), c.model)).toBe(c.want)
            })
        }
    })

    describe('reserveInputCount', () => {
        for (const c of v.reserve_input) {
            it(c.name, () => {
                for (const body of forms(c.body)) {
                    expect(reserveInputCount(opOf(c.op), c.model, body, c.max_output)).toEqual({
                        count: c.count,
                        boundVersion: c.bound_version,
                    })
                }
            })
        }
    })

    // A value past 2^53 is compared as the number it rounds to.
    describe('extractMaxOutput', () => {
        for (const c of v.extract_max_output) {
            it(c.name, () => {
                for (const body of forms(c.body)) {
                    if (c.err) expect(() => extractMaxOutput(body)).toThrow()
                    else expect(extractMaxOutput(body)).toBe(Number(c.want))
                }
            })
        }
    })

    describe('estimate', () => {
        for (const c of v.estimate) {
            it(c.name, () => {
                const policy = { maxOutputByModel: c.by_model ?? {}, fallbackMaxOutput: c.fallback }
                for (const body of forms(c.body)) {
                    if (c.err === 'max_output_required') {
                        expect(() => estimate(c.model, body, policy)).toThrow(MaxOutputRequiredError)
                    } else if (c.err === 'decode') {
                        expect(() => estimate(c.model, body, policy)).toThrow(TypeError)
                    } else {
                        expect(estimate(c.model, body, policy)).toEqual(c.want)
                    }
                }
            })
        }
    })

    describe('streamableRequest', () => {
        for (const c of v.streamable) {
            it(JSON.stringify(c.body), () => {
                for (const body of forms(c.body)) expect(streamableRequest(body)).toBe(c.want)
            })
        }
    })

    describe('parseImageRequestN', () => {
        for (const c of v.image_n) {
            it(JSON.stringify(c.body), () => {
                for (const body of forms(c.body)) {
                    if (c.err) expect(() => parseImageRequestN(body)).toThrow(c.err)
                    else expect(parseImageRequestN(body)).toEqual({ n: c.n, size: c.size, quality: c.quality })
                }
            })
        }
    })

    describe('messages', () => {
        for (const c of v.messages) {
            it(c.name, () => {
                expect(noFitMessage(c.model, c.sizing, c.misses)).toBe(c.no_fit)
                expect(reserveSizeFailureMessage(c.model, c.sizing, c.rejections, c.misses)).toBe(c.size_failure)
            })
        }
    })

    describe('admit', () => {
        for (const c of v.admit) {
            it(c.name, () => {
                const ops = c.ops.map(opOf)
                for (const body of forms(c.body)) {
                    ops.forEach((op: SizingOp, i: number) => {
                        expect(advertisedMaxPrice(op, c.model, body, c.sizing, c.fee_bps ?? 0)).toBe(c.prices[i])
                    })
                    expect(admitEstimate(ops, c.model, body, c.sizing, c.fee_bps)).toBe(c.want)
                }
            })
        }
    })

    it('resolveUsePrivacy', () => {
        for (const c of v.use_privacy) {
            expect(resolveUsePrivacy(c.config, c.allow, c.pref), JSON.stringify(c)).toBe(c.want)
        }
    })

    it('busyRetryWait', () => {
        for (const c of v.busy_wait) {
            const sched: number[] | null = c.sweep_delay_ms
            const delay = sched === null ? undefined : (sweep: number) => sched[sweep] ?? 0
            expect(busyRetryWait(c.sweep, c.hint_ms, c.remaining_ms, delay), JSON.stringify(c)).toEqual({
                delayMs: c.delay_ms,
                ok: c.ok,
            })
        }
    })
})
